/**
 * Hand-written (not generated by orval), same infrastructure as myBox.ts /
 * achievements.ts.
 */
import { customFetch } from "./custom-fetch";

export type WodFormat = "for_time" | "amrap" | "max_reps";

export type WodResultInput = {
  timeSeconds: number | null;
  rounds: number | null;
  reps: number | null;
  scaled: boolean;
  notes: string | null;
};

export type TodayWod = {
  wodOfDayId: string;
  wodId: string;
  name: string;
  format: WodFormat;
  timeCapMinutes: number | null;
  description: string;
  notes: string | null;
  sessionDate: string;
  myResult: WodResultInput | null;
};

export async function getTodayWod(userId: string): Promise<{ wod: TodayWod | null }> {
  return customFetch<{ wod: TodayWod | null }>(
    `/api/wod/today?userId=${encodeURIComponent(userId)}`,
  );
}

export async function submitWodResult(params: {
  userId: string;
  wodOfDayId: string;
  timeSeconds?: number;
  rounds?: number;
  reps?: number;
  scaled: boolean;
  notes?: string;
}): Promise<void> {
  await customFetch("/api/wod-results", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(params),
  });
}

export type WodHistoryEntry = {
  id: string;
  timeSeconds: number | null;
  rounds: number | null;
  reps: number | null;
  scaled: boolean;
  notes: string | null;
  createdAt: string;
  sessionDate: string;
  wodId: string;
  name: string;
  format: WodFormat;
};

export async function getWodHistory(userId: string): Promise<{ results: WodHistoryEntry[] }> {
  return customFetch<{ results: WodHistoryEntry[] }>(
    `/api/wod-results?userId=${encodeURIComponent(userId)}`,
  );
}
